<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import {computed,ref,watch,onMounted,onUnmounted,nextTick} from 'vue';
import {Download,ShieldCheck,Minimize2,GripVertical} from 'lucide-vue-next';
import {useStudio} from '../store';import {downloadDescription} from '../../shared/downloads.mjs';import {clampWidget} from '../../shared/floating-widget.mjs';import DownloadControls from './DownloadControls.vue';
import DownloadTransferStatus from './DownloadTransferStatus.vue';
const s=useStudio(),element=ref(),dragPosition=ref(null),viewport=ref({width:window.innerWidth,height:window.innerHeight});const measuredSize=ref({width:410,height:290});let observer,drag,wasDragged=false;watch(element,el=>{observer?.disconnect();if(el){observer=new ResizeObserver(([entry])=>{measuredSize.value={width:entry.target.offsetWidth,height:entry.target.offsetHeight};});observer.observe(el);}});
const prefs=computed(()=>s.config.downloadWidget||{}),description=computed(()=>downloadDescription(s.install)),downloaded=computed(()=>((s.install.bytes||0)/1024**2).toFixed(1)),total=computed(()=>((s.install.total||0)/1024**2).toFixed(1));
const size=computed(()=>(prefs.value.collapsed?{width:48,height:48}:measuredSize.value));
const positionStyle=computed(()=>{const p=dragPosition.value||prefs.value.position;if(!p)return{};const bounded=clampWidget(p,size.value,viewport.value);return{left:bounded.x+'px',top:bounded.y+'px',right:'auto',bottom:'auto'};});
function details(){s.config.settingsCategory=description.value.category;s.config.downloadFocusToken=Date.now();s.tab='settings';}
function startDrag(event){if(event.button!==0||!event.target.closest('[data-download-drag]')||event.target.closest('button:not([data-download-drag])'))return;const r=element.value.getBoundingClientRect();drag={x:event.clientX,y:event.clientY,left:r.left,top:r.top};wasDragged=false;event.target.closest('[data-download-drag]').setPointerCapture(event.pointerId);}
function moveDrag(event){if(!drag)return;const dx=event.clientX-drag.x,dy=event.clientY-drag.y;if(!wasDragged&&Math.hypot(dx,dy)<4)return;wasDragged=true;const r=element.value.getBoundingClientRect();dragPosition.value=clampWidget({x:drag.left+dx,y:drag.top+dy},{width:r.width,height:r.height},viewport.value);event.preventDefault();}
function endDrag(){if(dragPosition.value)s.config.downloadWidget={...prefs.value,position:dragPosition.value};drag=null;dragPosition.value=null;setTimeout(()=>wasDragged=false,0);}
async function collapse(value){if(wasDragged){wasDragged=false;return;}const r=element.value.getBoundingClientRect();s.config.downloadWidget={...prefs.value,collapsed:value,position:prefs.value.position||{x:r.left,y:r.top}};await nextTick();}
function resize(){viewport.value={width:window.innerWidth,height:window.innerHeight};}onMounted(()=>window.addEventListener('resize',resize));onUnmounted(()=>{observer?.disconnect();window.removeEventListener('resize',resize);});
</script>
<template><aside v-if="['running','paused','error'].includes(s.install.state)&&s.tab!=='settings'" ref="element" :class="['floating-download',{'download-minimized':prefs.collapsed}]" :style="positionStyle" @pointerdown="startDrag" @pointermove="moveDrag" @pointerup="endDrag" @pointercancel="endDrag"><button v-if="prefs.collapsed" class="download-widget-icon" data-download-drag :title="ui(description.title+' · '+(s.install.percent||0)+'% · 拖动调整位置，点击展开')" :aria-label="ui(&quot;展开下载进度&quot;)" @click="collapse(false)"><svg class="download-widget-ring" viewBox="0 0 48 48"><circle cx="24" cy="24" r="20" fill="none" stroke="#eee6fa" stroke-width="3"/><circle cx="24" cy="24" r="20" fill="none" stroke="#8860d0" stroke-width="3" :stroke-dasharray="126*(s.install.percent||0)/100+' 126'" transform="rotate(-90 24 24)"/></svg><Download :size="19"/></button><template v-else><div class="download-widget-header" data-download-drag :title="ui(&quot;拖动标题栏可调整位置&quot;)"><GripVertical :size="14"/><ShieldCheck v-if="s.install.phase==='verifying'" :size="17"/><Download v-else :size="17"/><strong>{{ui(s.install.phase==='verifying'?'正在校验模型':s.install.state==='paused'?'下载已暂停':s.install.state==='error'?'下载需要重试':'正在下载模型')}}</strong><button class="text-button" @click="details">{{ui("查看详情")}}</button><button class="icon-button" :title="ui(&quot;收起为可拖动的小图标&quot;)" :aria-label="ui(&quot;收起下载进度&quot;)" @click="collapse(true)"><Minimize2 :size="16"/></button></div><p><strong>{{ui(description.title)}}</strong></p><small class="download-purpose">{{ui(description.purpose)}}</small><small class="download-filename">{{ui(s.install.name||s.install.message)}}</small><div class="progress download-progress"><i :style="{width:(s.install.percent||0)+'%'}"/></div><div class="download-stats"><span>{{ui(s.install.percent||0)}}%</span><span v-if="s.install.total">{{ui(downloaded)}} / {{ui(total)}} MB</span><span v-if="s.install.speed">{{ui((s.install.speed/1024**2).toFixed(1))}} MB/s</span></div><small v-if="s.install.fileCount>1">{{ui(s.install.fileIndex)}} / {{ui(s.install.fileCount)}}{{ui(" 个文件 · 总进度 ")}}{{ui(s.install.overallPercent||0)}}%</small><DownloadTransferStatus :install="s.install"/><small v-if="s.install.phase==='retrying'">{{ui(s.install.message)}}</small><DownloadControls/></template></aside></template>
